using System;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "AncientHelmOmenData", menuName = "Data/Battle/Omens System/Omen Data/Cellarius/AncientHelmOmenData")]
public class AncientHelmOmenData : OmenData
{
	[NonSerialized]
	private OmenInstance omenInstance;

	protected Action<int> omenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		this.omenInstance = omenInstance;
		omenAction = delegate(int purifyAmount)
		{
			counter += purifyAmount;
			if (counter == TriggerAmount - 1)
			{
				omenInstance.PlayBlinkingFeedback();
			}
			else if (counter == TriggerAmount)
			{
				omenInstance.EnqueueOmenFeedbackAndPlay();
				omenInstance.StopBlinkingFeedback();
				ActivateOmenWithoutCounter();
				counter = 0;
			}
			else if (counter >= TriggerAmount)
			{
				omenInstance.StopBlinkingFeedback();
				counter = 0;
			}
			omenInstance.UpdateOmenCounter();
		};
		ReferenceSingleton<CellariusOmensHandler>.Instance.AncientHelmOmenAction = omenAction;
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<CellariusOmensHandler>.Instance.AncientHelmOmenAction = null;
	}

	public override string OmenConvertedDescription()
	{
		return CheckAppendCounterKeptBetweenBattlesDescription(Smart.Format(GetOmenRawLocalizedDescription(), TriggerAmount, BattleAction.GetActionDescription(ActionValue).LowercaseFirst().RemoveLast()));
	}
}
